package ch.hewa.screenshot;
import android.app.*;import android.content.*;import android.graphics.*;import android.hardware.display.*;import android.media.*;import android.media.projection.*;import android.os.*;import android.provider.MediaStore;import android.util.DisplayMetrics;import android.view.*;import android.widget.*;import java.io.*;
public class ServiceCapture extends Service{
 MediaProjection projection;VirtualDisplay display;ImageReader reader;Handler h=new Handler(Looper.getMainLooper());WindowManager wm;View bubble;boolean busy=false;
 public IBinder onBind(Intent i){return null;}
 public int onStartCommand(Intent i,int flags,int id){if(i==null)return START_NOT_STICKY;if("SHOT".equals(i.getAction())){shot();return START_NOT_STICKY;}NotificationChannel ch=new NotificationChannel("hewa","HEWA Screenshot",NotificationManager.IMPORTANCE_LOW);getSystemService(NotificationManager.class).createNotificationChannel(ch);PendingIntent pi=PendingIntent.getService(this,1,new Intent(this,ServiceCapture.class).setAction("SHOT"),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);Notification n=new Notification.Builder(this,"hewa").setSmallIcon(R.drawable.hewa_icon).setContentTitle("HEWA Screenshot attiva").setContentText("Tocca il pulsante flottante per catturare").addAction(new Notification.Action.Builder(R.drawable.hewa_icon,"Acquisisci",pi).build()).build();startForeground(10,n,android.content.pm.ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PROJECTION);Intent data=Build.VERSION.SDK_INT>=33?i.getParcelableExtra("data",Intent.class):i.getParcelableExtra("data");if(data==null){stopSelf();return START_NOT_STICKY;}projection=getSystemService(MediaProjectionManager.class).getMediaProjection(i.getIntExtra("result",0),data);projection.registerCallback(new MediaProjection.Callback(){public void onStop(){stopSelf();}},h);DisplayMetrics dm=getResources().getDisplayMetrics();reader=ImageReader.newInstance(dm.widthPixels,dm.heightPixels,PixelFormat.RGBA_8888,2);display=projection.createVirtualDisplay("HEWA",dm.widthPixels,dm.heightPixels,dm.densityDpi,DisplayManager.VIRTUAL_DISPLAY_FLAG_AUTO_MIRROR,reader.getSurface(),null,h);bubble();return START_NOT_STICKY;}
 void bubble(){if(!android.provider.Settings.canDrawOverlays(this))return;wm=getSystemService(WindowManager.class);TextView b=new TextView(this);b.setText("📷");b.setTextSize(25);b.setGravity(Gravity.CENTER);b.setBackgroundTintList(null);b.setBackgroundColor(0xff4b35b9);WindowManager.LayoutParams p=new WindowManager.LayoutParams(150,150,WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE,PixelFormat.TRANSLUCENT);p.gravity=Gravity.TOP|Gravity.END;p.y=240;wm.addView(b,p);bubble=b;b.setOnClickListener(v->{b.setVisibility(View.INVISIBLE);h.postDelayed(()->{shot();h.postDelayed(()->{if(bubble!=null)bubble.setVisibility(View.VISIBLE);},700);},250);});}
 void shot(){if(reader==null||busy)return;busy=true;h.postDelayed(()->{Image img=null;try{img=reader.acquireLatestImage();if(img==null){Toast.makeText(this,"Riprova",Toast.LENGTH_SHORT).show();return;}Image.Plane p=img.getPlanes()[0];int w=img.getWidth(),height=img.getHeight(),stride=p.getRowStride(),pixel=p.getPixelStride();Bitmap big=Bitmap.createBitmap(stride/pixel,height,Bitmap.Config.ARGB_8888);big.copyPixelsFromBuffer(p.getBuffer());Bitmap bmp=Bitmap.createBitmap(big,0,0,w,height);big.recycle();ContentValues v=new ContentValues();v.put(MediaStore.Images.Media.DISPLAY_NAME,"HEWA_"+System.currentTimeMillis()+".png");v.put(MediaStore.Images.Media.MIME_TYPE,"image/png");v.put(MediaStore.Images.Media.RELATIVE_PATH,"Pictures/HEWA Screenshot");android.net.Uri uri=getContentResolver().insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI,v);try(OutputStream o=getContentResolver().openOutputStream(uri)){bmp.compress(Bitmap.CompressFormat.PNG,100,o);}bmp.recycle();Toast.makeText(this,"Screenshot salvato",Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(this,e.toString(),Toast.LENGTH_LONG).show();}finally{if(img!=null)img.close();busy=false;}},250);}
 public void onDestroy(){if(bubble!=null&&wm!=null)wm.removeView(bubble);if(display!=null)display.release();if(reader!=null)reader.close();if(projection!=null)projection.stop();super.onDestroy();}
}